package ru.truetv.launcher;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.concurrent.*;

/** Owner-requested IR diagnostics and private draft. No system mapping is installed here. */
public final class IrRemoteActivity extends Activity {
 private static final String[] KEYS={"up","down","left","right","ok","back","home","menu","volume_up","volume_down","mute","power"};
 private static final String[] RU={"Вверх","Вниз","Влево","Вправо","OK","Назад","Домой","Меню","Громкость +","Громкость −","Без звука","Питание"};
 private static final String[] EN={"Up","Down","Left","Right","OK","Back","Home","Menu","Volume +","Volume −","Mute","Power"};
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());
 private final IrDiagnostics.Runner runner=RootCommand::run;
 private SharedPreferences prefs;private TextView status,report;private Button diagnose,learn,copy,cancel;private volatile boolean active;private Future<?> task;private int generation;private String appearance;private boolean exportPending;private ReportExport.Result lastExport;
 protected void onCreate(Bundle state){appearance=Ui.prepare(this);super.onCreate(state);Ui.bars(this);prefs=getSharedPreferences("ir_draft",MODE_PRIVATE);
  LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(Ui.dp(this,24),Ui.dp(this,16),Ui.dp(this,24),Ui.dp(this,12));Ui.backdrop(this,root);setContentView(root);
  root.addView(Ui.label(this,w("Настройка ИК-пульта · диагностика","IR remote setup · diagnostics"),22));
  TextView help=Ui.label(this,w("Для встроенного ИК-приёмника и имеющегося root. Сначала соберите отчёт и проверьте коды кнопок. Это черновик: управление другим пультом ещё не включается. Приём протокола зависит от драйвера и прошивки.","For the built-in IR receiver and existing root. Collect a report and check button codes first. This is a draft: another remote does not control the device yet. Protocol reception depends on driver and firmware."),15);help.setTextColor(Ui.muted(this));help.setPadding(0,Ui.dp(this,8),0,Ui.dp(this,8));root.addView(help);
  LinearLayout buttons=new LinearLayout(this);diagnose=button(buttons,w("Проверить приёмник","Check receiver"),this::diagnose);learn=button(buttons,w("Коды кнопок","Button codes"),this::choose);copy=button(buttons,w("Отчёт","Report"),this::export);root.addView(buttons);
  status=Ui.label(this,"",15);status.setPadding(0,Ui.dp(this,8),0,Ui.dp(this,8));root.addView(status);
  cancel=Ui.tvButton(this,w("Прекратить чтение","Stop reading"));cancel.setOnClickListener(v->stop());cancel.setVisibility(View.GONE);root.addView(cancel,new LinearLayout.LayoutParams(-1,Ui.dp(this,44)));
  ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);report=Ui.label(this,"",14);report.setTypeface(android.graphics.Typeface.MONOSPACE);report.setPadding(Ui.dp(this,8),Ui.dp(this,8),Ui.dp(this,8),Ui.dp(this,16));scroll.addView(report);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  if(state!=null)exportPending=state.getBoolean("export_pending");status.setText(w("Применение карты пока недоступно: нужен отчёт этой прошивки. Системные файлы не изменяются.","Applying a map is unavailable until this firmware is inspected. System files stay unchanged."));refresh();diagnose.requestFocus();
 }
 private String w(String ru,String en){return Ui.word(this,ru,en);}
 private String name(int i){return w(RU[i],EN[i]);}
 private Button button(LinearLayout row,String title,Runnable run){Button b=Ui.tvButton(this,title);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,Ui.dp(this,48),1);if(row.getChildCount()>0)p.leftMargin=Ui.dp(this,8);row.addView(b,p);b.setOnClickListener(v->{if(!active)run.run();});return b;}
 private void busy(boolean value){active=value;diagnose.setEnabled(!value);learn.setEnabled(!value);copy.setEnabled(!value);cancel.setVisibility(value?View.VISIBLE:View.GONE);if(value)cancel.requestFocus();else diagnose.requestFocus();}
 private void deliver(int id,Runnable run){main.post(()->{if(id==generation&&!isFinishing()&&!isDestroyed())run.run();});}
 private void diagnose(){final int id=++generation;busy(true);status.setText(w("Подтвердите root в системном запросе. Проверка занимает до 90 секунд…","Approve the root prompt. Diagnostics may take up to 90 seconds…"));task=worker.submit(()->{try{String value=IrDiagnostics.collect(runner);deliver(id,()->{prefs.edit().putString("report",device()+value).apply();busy(false);status.setText(w("Отчёт готов. Применение карты ещё не реализовано для этой прошивки. Скопируйте отчёт для проверки драйвера.","Report ready. This firmware has no mapping adapter yet. Copy the report for driver review."));refresh();});}catch(Exception e){failed(id,e);}});}
 private String device(){return "True TV Launcher "+BuildConfig.VERSION_NAME+" · IR diagnostics\nAndroid "+Build.VERSION.RELEASE+" / SDK "+Build.VERSION.SDK_INT+"\nModel: "+Build.MODEL+"\nBoard: "+Build.BOARD+"\nBuild: "+Build.DISPLAY+"\n\n";}
 private void failed(int id,Exception error){deliver(id,()->{busy(false);status.setText(w("Чтение не завершено. Root должен быть установлен и разрешён лаунчеру. Отсутствие ИК-лога не означает несовместимость пульта.\n","Reading did not finish. Existing root must be granted to this launcher. An absent IR log does not prove incompatibility.\n")+error.getClass().getSimpleName()+": "+String.valueOf(error.getMessage()));});}
 private void choose(){String[] rows=new String[KEYS.length];for(int i=0;i<rows.length;i++)rows[i]=name(i)+"  ·  "+prefs.getString(KEYS[i],"—");ChoiceDialog.show(this,w("Черновик кнопок · не применяется","Button draft · not applied"),rows,0,this::codeMenu);}
 private void codeMenu(int at){ActionSheet.show(this,name(at),new ActionSheet.Item(w("Считать код из ИК-лога","Read code from IR log"),"replace",()->capture(at)),new ActionSheet.Item(w("Ввести код вручную","Enter code manually"),"tune",()->manual(at)),new ActionSheet.Item(w("Удалить из черновика","Remove from draft"),"remove",()->{prefs.edit().remove(KEYS[at]).apply();refresh();}));}
 private void capture(int at){final int id=++generation;busy(true);status.setText(w("Подготовка чтения. Подтвердите root…","Preparing capture. Approve root…"));task=worker.submit(()->{try{IrDiagnostics.root(runner);IrCodes.Learning learning=new IrCodes.Learning(IrDiagnostics.log(runner));deliver(id,()->status.setText(name(at)+w(": нажмите нужную кнопку дважды в течение 20 секунд. Старые записи игнорируются. Ничего не переназначается.",": press the target button twice within 20 seconds. Old lines are ignored. Nothing is remapped.")));long end=System.nanoTime()+20000000000L;while(!Thread.currentThread().isInterrupted()&&System.nanoTime()<end){Thread.sleep(800);IrCodes.Code code=learning.accept(IrDiagnostics.log(runner));if(code!=null){deliver(id,()->{busy(false);confirm(at,code);});return;}}deliver(id,()->{busy(false);status.setText(w("Два новых совпадающих кода не получены. В прошивке может быть отключён ИК-лог или другой формат. Это не проверка совместимости; скопируйте отчёт. Отладка драйвера автоматически не включается.","No two matching new codes received. IR logging may be disabled or use another format. This is not a compatibility verdict; copy the report. Driver debug is not enabled automatically."));});}catch(Exception e){failed(id,e);}});}
 private void confirm(int at,IrCodes.Code code){ActionSheet.show(this,name(at)+" · "+code.wire(),new ActionSheet.Item(w("Сохранить только в черновик","Save to draft only"),"info",()->{prefs.edit().putString(KEYS[at],code.wire()).apply();refresh();status.setText(w("Код сохранён локально. Управление приставкой не изменилось.","Code saved locally. Device controls are unchanged."));}));}
 private void manual(int at){Dialog dialog=new Dialog(this);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(Ui.dp(this,16),Ui.dp(this,16),Ui.dp(this,16),Ui.dp(this,12));panel.setBackground(Ui.surface(this,Ui.panel(this),Ui.border(this),14));panel.addView(Ui.label(this,name(at)+w(" · код в hex"," · hex code"),20));panel.addView(Ui.label(this,w("Формат ffff:ff — адрес NEC и команда. Если адрес неизвестен: ?:ff. Код берите из отчёта, без догадок.","Use ffff:ff for NEC customer and command; ?:ff if the customer is unknown. Use observed codes, not guesses."),14));EditText input=new EditText(this);input.setSingleLine();input.setTextColor(Ui.ink(this));input.setText(prefs.getString(KEYS[at],""));panel.addView(input);TextView error=Ui.label(this,"",14);error.setTextColor(Ui.DISABLED_RED);panel.addView(error);Button save=Ui.tvButton(this,w("Сохранить черновик","Save draft"));panel.addView(save);save.setOnClickListener(v->{try{IrCodes.Code code=IrCodes.fromWire(input.getText().toString().trim());prefs.edit().putString(KEYS[at],code.wire()).apply();dialog.dismiss();refresh();}catch(IllegalArgumentException e){error.setText(w("Нужен формат ffff:ff или ?:ff","Expected ffff:ff or ?:ff"));}});Button back=Ui.tvButton(this,w("Отмена","Cancel"));panel.addView(back);back.setOnClickListener(v->dialog.dismiss());dialog.setContentView(panel);dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.show();dialog.getWindow().setLayout(Math.min(Ui.dp(this,500),getResources().getDisplayMetrics().widthPixels-Ui.dp(this,32)),-2);input.requestFocus();}
 private String text(){StringBuilder result=new StringBuilder(prefs.getString("report",device()+w("Диагностика ещё не запускалась.\n","Diagnostics not run yet.\n")));result.append("\nIR DRAFT — NOT APPLIED / НЕ ПРИМЕНЁН\nNEC customer:command (hex); ? = unknown customer\n");for(String key:KEYS)result.append(key).append('=').append(prefs.getString(key,"—")).append('\n');return result.toString();}
 private void refresh(){report.setText(text());}
 private void copy(){((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("IR diagnostic / private draft",text()));Ui.toast(this,"Отчёт скопирован. Отправьте его для проверки драйвера.","Report copied. Send it for driver review.");}
 private void export(){ActionSheet.show(this,w("Отчёт ИК-приёмника","IR receiver report"),new ActionSheet.Item(w("Копировать текст","Copy text"),"info",this::copy),new ActionSheet.Item(w("Сохранить в «Загрузки»","Save to Downloads"),"market",this::save));}
 private boolean storageAllowed(){return Build.VERSION.SDK_INT<23||Build.VERSION.SDK_INT>=29||(checkSelfPermission(android.Manifest.permission.WRITE_EXTERNAL_STORAGE)==android.content.pm.PackageManager.PERMISSION_GRANTED&&checkSelfPermission(android.Manifest.permission.READ_EXTERNAL_STORAGE)==android.content.pm.PackageManager.PERMISSION_GRANTED);}
 private void save(){if(!storageAllowed()){exportPending=true;requestPermissions(new String[]{android.Manifest.permission.READ_EXTERNAL_STORAGE,android.Manifest.permission.WRITE_EXTERNAL_STORAGE},93);return;}exportPending=false;try{lastExport=ReportExport.save(this,text());status.setText(w("Отчёт сохранён в «Загрузки»:\n","Report saved to Downloads:\n")+lastExport.location);}catch(java.io.IOException|RuntimeException e){status.setText(w("Не удалось сохранить в «Загрузки»: ","Cannot save to Downloads: ")+e.getMessage());}}
 public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==93){boolean pending=exportPending;exportPending=false;if(pending&&results.length>0&&storageAllowed())save();else status.setText(w("Отчёт не сохранён: для папки «Загрузки» разрешите доступ к хранилищу в свойствах лаунчера.","Report not saved: allow storage access in launcher App info to use Downloads."));}}
 protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putBoolean("export_pending",exportPending);}
 private void stop(){generation++;if(task!=null)task.cancel(true);busy(false);status.setText(w("Чтение остановлено. Черновик сохранён; драйвер не менялся.","Reading stopped. Draft retained; driver unchanged."));}
 protected void onResume(){super.onResume();if(!Ui.appearance(this).equals(appearance))recreate();}
 protected void onStop(){if(active)stop();super.onStop();}
 protected void onDestroy(){generation++;if(task!=null)task.cancel(true);worker.shutdownNow();super.onDestroy();}
}
